description_text:
Hi, we have begun using QuotaGuard static for a client of ours and I just wanted to get confirmation regarding HTTPS communication. I have seen your documentation where you say...      "When you make a request via the proxy to an HTTPS endpoint your client should transparently issue a CONNECT request rather than a basic GET request."     Do I need to do this manually via the code? At present I am using the code below - do I need to change this in some way? I look forward to your reply.                 //Extract proxy connection details
              var proxyUrl = ConfigProperties.QuotaGuardStaticUrl;
              var proxyUri = new System.Uri(proxyUrl);
              var cleanProxyURL = proxyUri.Scheme + "://" + proxyUri.Host + ":" + proxyUri.Port;
              var user = proxyUri.UserInfo.Split(':')[0];
              var password = proxyUri.UserInfo.Split(':')[1];
  
              result = new NameValueCollection();
  
              WebRequest webRequest = WebRequest.Create(uri);
              webRequest.ContentType = "application/x-www-form-urlencoded";
              webRequest.Method = "POST";
              byte[] bytes = Encoding.ASCII.GetBytes(BuildParametersString(parameters));
  
              var myProxy = new WebProxy();
              var newUri = new Uri(cleanProxyURL);
              // Associate the newUri object to 'myProxy' object so that new myProxy settings can be set.
              myProxy.Address = newUri;
              // Create a NetworkCredential object and associate it with the 
              // Proxy property of request object.
              myProxy.Credentials = new NetworkCredential(user, password);
              webRequest.Proxy = myProxy;
  
              Stream os = null;
              try
              {
                  webRequest.ContentLength = bytes.Length;   //Count bytes to send
                  os = webRequest.GetRequestStream();
                  os.Write(bytes, 0, bytes.Length);         //Send it
              }
              catch (WebException ex)
              {
                  _errormessage = ex.Message;
                  return false;
              }
              finally
              {
                  if (os != null)
                  {
                      os.Close();
                  }
              }
